#include <iostream>

using namespace std;

/**
 * Problem: 23661 - Bit Mask
 * 
 * 解題思路：
 * 1. 給定 N, L, U，尋找 M 使得 L <= M <= U，且 N | M 最大。
 * 2. 若有多個 M 滿足最大化 N | M，則選擇最小的 M。
 * 3. 使用貪心演算法從最高位 (第 31 位) 向低位處理。
 * 4. 對於每一位 i：
 *    - 若 N 的第 i 位為 0：
 *        - 我們希望 M 的第 i 位為 1，以增加 N | M。
 *        - 檢查若將 M 的第 i 位設為 1，是否有可能維持在 <= U。
 *        - 若可行，則設為 1。
 *    - 若 N 的第 i 位為 1：
 *        - 我們希望 M 的第 i 位為 0，以最小化 M (不影響 N | M)。
 *        - 檢查若將 M 的第 i 位設為 0，是否有可能維持在 >= L。
 *        - 如果即使後面位元全部設為 1 也無法達到 L，則此位必須設為 1。
 */

int main() {
    unsigned int n, l, u;
    while (cin >> n >> l >> u) {
        unsigned int m = 0;
        for (int i = 31; i >= 0; i--) {
            unsigned int bit = (1U << i);
            if (n & bit) {
                // N 該位為 1，希望 M 該位為 0
                // 但如果 M 該位為 0，剩餘位全為 1 仍小於 L，則此位必須為 1
                if ((m | (bit - 1)) < l) {
                    m |= bit;
                }
            } else {
                // N 該位為 0，希望 M 該位為 1
                // 只要 M 該位為 1 後不超過 U，就設為 1
                if ((m | bit) <= u) {
                    m |= bit;
                }
            }
        }
        cout << m << endl;
    }
    return 0;
}
